import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Crumbs","description":"","frontmatter":{},"headers":[],"relativePath":"components/crumbs.md","filePath":"components/crumbs.md"}'),n={name:"components/crumbs.md"};function s(i,e,h,d,c,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="crumbs" tabindex="-1">Crumbs <a class="header-anchor" href="#crumbs" aria-label="Permalink to &quot;Crumbs&quot;">​</a></h1><p>Crumbs is a trail of places that shows where the user is.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it above the title of a page (in the <code>crumbs</code> of a <a href="./page-header">PageHeader</a>) or next to the brand in a <a href="./topbar">Topbar</a>. The last place is the current one. A trail is not an action: to go somewhere else, use a link or a button.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code></td><td>required</td><td>The places, <code>{ label, href?, onclick? }[]</code></td></tr><tr><td><code>label</code></td><td></td><td>The name of the trail</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The text is caption in the color of the text around it, and the chevrons are faint; a place with <code>href</code> is a link and one with <code>onclick</code> a button, both in the same color and underlined on hover. The last place is the current one (<code>aria-current=&quot;page&quot;</code>) and cannot be pressed. The places are gap-2xs from the chevrons that separate them. Each place is at most 12rem wide and ends with an ellipsis beyond it, with the full text on hover and on keyboard focus; when the width runs out the places shrink down to 4rem, and the trail shrinks before what stands next to it. Inside a component with a height (a toolbar, a list item) the text is trimmed to its ink.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/crumbs/" title="Crumbs" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/crumbs/" target="_blank" rel="noopener">Crumbs</a></figcaption></figure>',10)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
